INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4587203, 660078, 62318, '<td valign="top">Can''t go wrong with Dick''s. Especially that cow on the shakes. Ready to go and yummy to eat.</td>', 'Can''t go wrong with Dick''s. Especially that cow on the shakes. Ready to go and yummy to eat.', '2008-03-26 00:06:41.000000', NULL, 1),
(4587212, 662064, 70000, '<td valign="top">Beautiful, a true classic. The bokeh is incredible and your lighting is fantastic. A winner in my book!</td>', 'Beautiful, a true classic. The bokeh is incredible and your lighting is fantastic. A winner in my book!', '2008-03-26 00:09:16.000000', NULL, 1),
(4587217, 661652, 70000, '<td valign="top">Very cute. I like the simplicity of it. The bokeh is pretty and the couple is dark enough that they stand out. Lovely intimate pair</td>', 'Very cute. I like the simplicity of it. The bokeh is pretty and the couple is dark enough that they stand out. Lovely intimate pair', '2008-03-26 00:09:54.000000', NULL, 1),
(4587219, 662021, 19982, '<td valign="top">I like the contact the girl has made with the viewer even while her position with her head and hand on his chest implies intimacy.  I''m undecided about either direction of his look or the position of his hand.  Both seem somewhat out of place (his hand just looks a little odd to me).  And the white on the right... I can''t decide if the "negative space" here is working for the image or against it.</td>', 'I like the contact the girl has made with the viewer even while her position with her head and hand on his chest implies intimacy.  I''m undecided about either direction of his look or the position of his hand.  Both seem somewhat out of place (his hand just looks a little odd to me).  And the white on the right... I can''t decide if the "negative space" here is working for the image or against it.', '2008-03-26 00:10:25.000000', NULL, 1),
(4587220, 662198, 70000, '<td valign="top">HAHA. what an awesome wide angle image. Very unique take on intimacy, but really...that is as intimate and vulnerable as someone can get without being sick in bed all snotty and throwing up. Nice bw</td>', 'HAHA. what an awesome wide angle image. Very unique take on intimacy, but really...that is as intimate and vulnerable as someone can get without being sick in bed all snotty and throwing up. Nice bw', '2008-03-26 00:10:52.000000', NULL, 1),
(4587226, 662132, 19982, '<td valign="top">Love the lighting.</td>', 'Love the lighting.', '2008-03-26 00:11:25.000000', NULL, 1),
(4587228, 660725, 70000, '<td valign="top">lovely. The girl on the right looking into the camera just makes this. Beautiful image</td>', 'lovely. The girl on the right looking into the camera just makes this. Beautiful image', '2008-03-26 00:11:47.000000', NULL, 1),
(4587234, 661632, 70000, '<td valign="top">Haha! Awesome personification. Very simple and direct. I like this a lot</td>', 'Haha! Awesome personification. Very simple and direct. I like this a lot', '2008-03-26 00:12:29.000000', NULL, 1),
(4587247, 661336, 19982, '<td valign="top">Interesting choice of colors.  Perhaps a view I should only see with someone I am intimate with ... but otherwise the image doesn''t really convey "intimacy" to me.</td>', 'Interesting choice of colors.  Perhaps a view I should only see with someone I am intimate with ... but otherwise the image doesn''t really convey "intimacy" to me.', '2008-03-26 00:14:46.000000', NULL, 1),
(4587254, 660449, 70000, '<td valign="top">I love the repetition pattern going on with the monkey''s faces. They look so cuddly this is a perfect shot for intimacy</td>', 'I love the repetition pattern going on with the monkey''s faces. They look so cuddly this is a perfect shot for intimacy', '2008-03-26 00:15:20.000000', NULL, 1),
(4587256, 661000, 19982, '<td valign="top">Girl''s best friend?  :-)<br/> <br/>Cute puppy... would have liked to have seen the girl hugging it close or something.</td>', 'Girl''s best friend?  :-) Cute puppy... would have liked to have seen the girl hugging it close or something.', '2008-03-26 00:15:40.000000', NULL, 1),
(4587259, 662275, 70000, '<td valign="top">This is beautiful! It is cool that you left it in color though because people tend to make this kind of shot black and white so they can depend on the nostalgia of it, but you have relied on the lovely candid moment, good framing and depth of field to make a strong color image. Nice</td>', 'This is beautiful! It is cool that you left it in color though because people tend to make this kind of shot black and white so they can depend on the nostalgia of it, but you have relied on the lovely candid moment, good framing and depth of field to make a strong color image. Nice', '2008-03-26 00:16:33.000000', NULL, 1),
(4587266, 662241, 70000, '<td valign="top">This would say intimacy to me more if she didn''t look so tense and uncomfortable. This makes their situation seem more out of place than intimate in my opinion.</td>', 'This would say intimacy to me more if she didn''t look so tense and uncomfortable. This makes their situation seem more out of place than intimate in my opinion.', '2008-03-26 00:17:27.000000', NULL, 1),
(4587272, 660131, 36006, '<td valign="top">As a photographer, and within the confines of the challenge it up to you to convince me.<br/> <br/>this is as intimate as rock concert, or a marathon. I get the impression of a baby sitter watching over his charge.<br/> <br/>Sorry, but I am not convinced.<br/> <br/>Try again.</td>', 'As a photographer, and within the confines of the challenge it up to you to convince me. this is as intimate as rock concert, or a marathon. I get the impression of a baby sitter watching over his charge. Sorry, but I am not convinced. Try again.', '2008-03-26 00:18:25.000000', NULL, 1),
(4587280, 661937, 19982, '<td valign="top">CUTE!!! Now *this* says intimacy to me... the closeness, the bare feet, the covers.  Love the B&amp;W tones.  Cute toe nails too.  :-)</td>', 'CUTE!!! Now *this* says intimacy to me... the closeness, the bare feet, the covers.  Love the B&W tones.  Cute toe nails too.  :-)', '2008-03-26 00:20:18.000000', NULL, 1),
(4587305, 661341, 19982, '<td valign="top">I swear the window frame (the "X" behind them) is more in focus than the B&amp;G are... I know, it''s difficult.  The camera wants to focus on the highest contrast that is nearest the AF point.  And it''s so difficult to see what it locked on inside the viewfinder...   <br/> <br/>As for the theme... I think a little closer ... the "almost kiss" would have conveyed intimacy a little better.  <br/> <br/>Things to improve:  The focus as already mentioned.  The flash output.  The good thing is that the flash is above the camera.  The bad thing is that it caused the bouquet to cast shadows on the bride.  A more diffused light source would have solved that.  (bouncing the light off the ceiling, for example)</td>', 'I swear the window frame (the "X" behind them) is more in focus than the B&G are... I know, it''s difficult.  The camera wants to focus on the highest contrast that is nearest the AF point.  And it''s so difficult to see what it locked on inside the viewfinder...    As for the theme... I think a little closer ... the "almost kiss" would have conveyed intimacy a little better.   Things to improve:  The focus as already mentioned.  The flash output.  The good thing is that the flash is above the camera.  The bad thing is that it caused the bouquet to cast shadows on the bride.  A more diffused light source would have solved that.  (bouncing the light off the ceiling, for example)', '2008-03-26 00:24:13.000000', NULL, 1),
(4587330, 661132, 19982, '<td valign="top">By his expression, he looks like he may be sharing an intimate moment (even if in an awkward place).  She, however, doesn''t look at all interested in him ... perhaps either concerned or amused at the face above her, I can''t tell.  <br/> <br/>Suggestions for improvement:  Perhaps have her lay her head on his shoulder.  She could either look into his eyes or she could even look down at the floor ... as if to simply be comforted to be in his arms.</td>', 'By his expression, he looks like he may be sharing an intimate moment (even if in an awkward place).  She, however, doesn''t look at all interested in him ... perhaps either concerned or amused at the face above her, I can''t tell.   Suggestions for improvement:  Perhaps have her lay her head on his shoulder.  She could either look into his eyes or she could even look down at the floor ... as if to simply be comforted to be in his arms.', '2008-03-26 00:28:27.000000', NULL, 1),
(4587337, 662037, 91735, '<td valign="top">I really like this photo. I love the relationship it shows. the love that you can see they have for each other. I like that this is one of the photos that thought beyond intimacy being about sex.</td>', 'I really like this photo. I love the relationship it shows. the love that you can see they have for each other. I like that this is one of the photos that thought beyond intimacy being about sex.', '2008-03-26 00:29:54.000000', NULL, 1),
(4587340, 662258, 19982, '<td valign="top">I like that they are all "connected" by touch.  It''s not really an intimate scene the way I refer to intimate.  But your allows me to overlook that and decide that yes, this could be an intimate group of friends.<br/> <br/>Lovely B&amp;W toning, by the way!</td>', 'I like that they are all "connected" by touch.  It''s not really an intimate scene the way I refer to intimate.  But your allows me to overlook that and decide that yes, this could be an intimate group of friends. Lovely B&W toning, by the way!', '2008-03-26 00:30:13.000000', NULL, 1),
(4587343, 661390, 91735, '<td valign="top">I like this photo. I reminds me of my great-grandparents before they passed. true love never dies.</td>', 'I like this photo. I reminds me of my great-grandparents before they passed. true love never dies.', '2008-03-26 00:30:43.000000', NULL, 1),
(4587352, 660999, 19982, '<td valign="top">The position of their eyes (both girl and boy) work well here.  He, looking at her, in anticipation.  She, looking down, as if in contemplation of what is to come.  The touch ... both forehead to head and hand to cheek connote intimacy to me.<br/> <br/>The lighting could have used a little more 3D appearance to it, but I love the B&amp;W toning.  Good job!</td>', 'The position of their eyes (both girl and boy) work well here.  He, looking at her, in anticipation.  She, looking down, as if in contemplation of what is to come.  The touch ... both forehead to head and hand to cheek connote intimacy to me. The lighting could have used a little more 3D appearance to it, but I love the B&W toning.  Good job!', '2008-03-26 00:32:39.000000', NULL, 1),
(4587370, 660131, 19982, '<td valign="top">Intimacy, to me, means "closeness".  I don''t see a closeness in the image (other than a small hint at it by way of holding hands), and the title actually refers to the opposite ... so "not close" as to having been forgotten .. which, to me, also cancels the hand holding by making me think that the image isn''t about those who are holding hands, but rather, is actually about a baby that isn''t even in the frame.</td>', 'Intimacy, to me, means "closeness".  I don''t see a closeness in the image (other than a small hint at it by way of holding hands), and the title actually refers to the opposite ... so "not close" as to having been forgotten .. which, to me, also cancels the hand holding by making me think that the image isn''t about those who are holding hands, but rather, is actually about a baby that isn''t even in the frame.', '2008-03-26 00:37:09.000000', NULL, 1),
(4587373, 661614, 19982, '<td valign="top">Cute...  and blech at the same time!!!  lol<br/> <br/>I''ve never been able to let a dog lick me because I just can''t get over what a dog licks with his tongue!  :0<br/> <br/>In any case, the lighting is excellent, exhibiting both light and shadow and the colors are good.</td>', 'Cute...  and blech at the same time!!!  lol I''ve never been able to let a dog lick me because I just can''t get over what a dog licks with his tongue!  :0 In any case, the lighting is excellent, exhibiting both light and shadow and the colors are good.', '2008-03-26 00:39:00.000000', NULL, 1),
(4587381, 660060, 19982, '<td valign="top">Not sure about cutting her belly off (especially since the one finger hints that more should be there).  But the B&amp;W toning is great and I love the look of intimacy shared between them.</td>', 'Not sure about cutting her belly off (especially since the one finger hints that more should be there).  But the B&W toning is great and I love the look of intimacy shared between them.', '2008-03-26 00:42:05.000000', NULL, 1),
(4587386, 661681, 19982, '<td valign="top">I love the shared kiss, the flowing dress, the B&amp;W toning.  I kinda wish his right hand was somehow more involved to add a greater sense of intimacy to the moment.</td>', 'I love the shared kiss, the flowing dress, the B&W toning.  I kinda wish his right hand was somehow more involved to add a greater sense of intimacy to the moment.', '2008-03-26 00:43:14.000000', NULL, 1),
(4587391, 661816, 19982, '<td valign="top">Pretty flower.  Lovely colors.  Not quite sure it fits the theme of intimacy.</td>', 'Pretty flower.  Lovely colors.  Not quite sure it fits the theme of intimacy.', '2008-03-26 00:44:07.000000', NULL, 1),
(4587402, 661754, 19982, '<td valign="top">I''m probably dense.  I don''t get the title...  or the image.<br/> <br/>The meaning of Intimacy varies from relationship to relationship, and within a given relationship. Intimacy has more to do with shared moments...  everyone in that image appears separate from one another (no intimacy is shown or implied).<br/> <br/>Anyway, it''s just not working for me... Not trying to put it down, just trying to explain how I react to it.</td>', 'I''m probably dense.  I don''t get the title...  or the image. The meaning of Intimacy varies from relationship to relationship, and within a given relationship. Intimacy has more to do with shared moments...  everyone in that image appears separate from one another (no intimacy is shown or implied). Anyway, it''s just not working for me... Not trying to put it down, just trying to explain how I react to it.', '2008-03-26 00:48:00.000000', NULL, 1),
(4587412, 661866, 19982, '<td valign="top">A lovely scene, to be sure.<br/> <br/>Some things I personally would prefer...  flattening the mother''s shirt just a bit so I could see the infant''s face just a bit more.  And realizing that it''s complicated, slightly better light on the parent''s faces (not enough to detract from the infant, who is the center of this image, but enough that they are not in darkness).  For example, the father''s neck is too bright, while his face is too dark.  Perhaps bringing the light around to the front just a little bit more would help?  Or else block the light reaching his neck so it doesn''t detract from his face...</td>', 'A lovely scene, to be sure. Some things I personally would prefer...  flattening the mother''s shirt just a bit so I could see the infant''s face just a bit more.  And realizing that it''s complicated, slightly better light on the parent''s faces (not enough to detract from the infant, who is the center of this image, but enough that they are not in darkness).  For example, the father''s neck is too bright, while his face is too dark.  Perhaps bringing the light around to the front just a little bit more would help?  Or else block the light reaching his neck so it doesn''t detract from his face...', '2008-03-26 00:52:06.000000', NULL, 1),
(4587413, 662082, 19982, '<td valign="top">Intimacy is generally a closeness between two people...  for me, this image doesn''t imply she is close to anyone, and the title tends to confirm that.</td>', 'Intimacy is generally a closeness between two people...  for me, this image doesn''t imply she is close to anyone, and the title tends to confirm that.', '2008-03-26 00:53:06.000000', NULL, 1),
(4587415, 660725, 19982, '<td valign="top">Lovely B&amp;W toning.  I love the look in the girl''s eye as she is obviously telling a secret.  And the smile on the other girl''s face implies that she is hanging on every word.  I like this image.  Well done.</td>', 'Lovely B&W toning.  I love the look in the girl''s eye as she is obviously telling a secret.  And the smile on the other girl''s face implies that she is hanging on every word.  I like this image.  Well done.', '2008-03-26 00:54:09.000000', NULL, 1),
(4587417, 661928, 19982, '<td valign="top">The image doesn''t really imply intimacy to me.  But your title at least hints that intimacy may soon be coming.  I *do* like the lighting, the colors and composition.</td>', 'The image doesn''t really imply intimacy to me.  But your title at least hints that intimacy may soon be coming.  I *do* like the lighting, the colors and composition.', '2008-03-26 00:57:57.000000', NULL, 1),
(4587429, 661200, 19982, '<td valign="top">There is another image in this challenge very similar to this one.  I loved it ... but no so much this one.  I''m trying to determine the difference.  I think there are a few things:  For some reason the color turns me off, it''s a "darker image".  The blurred foot keeps grabbing my attention and saying that something is wrong. And the top of the image just doesn''t feel finished.  I think you could have cropped it off.</td>', 'There is another image in this challenge very similar to this one.  I loved it ... but no so much this one.  I''m trying to determine the difference.  I think there are a few things:  For some reason the color turns me off, it''s a "darker image".  The blurred foot keeps grabbing my attention and saying that something is wrong. And the top of the image just doesn''t feel finished.  I think you could have cropped it off.', '2008-03-26 01:06:57.000000', NULL, 1),
(4587433, 660757, 19982, '<td valign="top">A lovely image, to be sure ... I mean, I love the lighting, and the girl and her pose are perfect.  But the image doesn''t seem to imply intimacy (closeness between two people) nor does the title.</td>', 'A lovely image, to be sure ... I mean, I love the lighting, and the girl and her pose are perfect.  But the image doesn''t seem to imply intimacy (closeness between two people) nor does the title.', '2008-03-26 01:08:39.000000', NULL, 1),
(4587437, 661732, 63503, '<td valign="top">I would have given you a 10 for this picture in the free study challenge, very sharp! great colors. I''ll take away 2 points for shoehorning it here.</td>', 'I would have given you a 10 for this picture in the free study challenge, very sharp! great colors. I''ll take away 2 points for shoehorning it here.', '2008-03-26 01:11:49.000000', NULL, 1),
