(4588316, 661654, 48588, '<td valign="top">Ha ha ha ... !</td>', 'Ha ha ha ... !', '2008-03-26 09:47:59.000000', NULL, 1),
(4588322, 660449, 48588, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2008-03-26 09:48:53.000000', NULL, 1),
