(4588343, 661754, 51679, '<td valign="top">It''s a free gift!  Why not take it?</td>', 'It''s a free gift!  Why not take it?', '2008-03-26 09:51:52.000000', NULL, 1),
(4588356, 660596, 48588, '<td valign="top">I go back &amp; forth on this one.  I''d like to see some spot of pure white in this image, but given the title I respect your intent to do something different in a B&amp;W.  I do wish her face was as sharp as her hair though, 6.</td>', 'I go back & forth on this one.  I''d like to see some spot of pure white in this image, but given the title I respect your intent to do something different in a B&W.  I do wish her face was as sharp as her hair though, 6.', '2008-03-26 09:54:24.000000', NULL, 1),
(4588365, 661866, 48588, '<td valign="top">I think getting rid of the diaper would''ve really enhanced this shot.</td>', 'I think getting rid of the diaper would''ve really enhanced this shot.', '2008-03-26 09:55:56.000000', NULL, 1),
(4588373, 660163, 48588, '<td valign="top">Good advice!</td>', 'Good advice!', '2008-03-26 09:57:03.000000', NULL, 1),
(4588384, 659875, 48588, '<td valign="top">Their wardrobe is sick, would love to know where you got it!</td>', 'Their wardrobe is sick, would love to know where you got it!', '2008-03-26 09:59:21.000000', NULL, 1),
(4588442, 661654, 76430, '<td valign="top">Not real imtimacy, but a play.  I shouldn''t talk, mine isn''t real either.  I know you had no control over the lighting, but the harsh lighting and shadows detract from it.</td>', 'Not real imtimacy, but a play.  I shouldn''t talk, mine isn''t real either.  I know you had no control over the lighting, but the harsh lighting and shadows detract from it.', '2008-03-26 10:16:35.000000', NULL, 1),
