(4588587, 662241, 76430, '<td valign="top">Very good meeting of the challenge.  Maybe a little too much shine on the skin, better than I could do though, but otherwise a very nice shot.</td>', 'Very good meeting of the challenge.  Maybe a little too much shine on the skin, better than I could do though, but otherwise a very nice shot.', '2008-03-26 11:03:24.000000', NULL, 1),
(4588588, 661390, 327, '<td valign="top">Well done. Handsome couple.</td>', 'Well done. Handsome couple.', '2008-03-26 11:03:25.000000', NULL, 1),
(4588596, 661576, 91900, '<td valign="top">Nice sense movement on the hands.  Intersting shadow on the wall.  Cut off heads always bothers me, but i think that is me, not a rule.</td>', 'Nice sense movement on the hands.  Intersting shadow on the wall.  Cut off heads always bothers me, but i think that is me, not a rule.', '2008-03-26 11:04:57.000000', NULL, 1),
