(4588613, 662244, 91900, '<td valign="top">Detail on the bottom seems washed out.  Nice range with background</td>', 'Detail on the bottom seems washed out.  Nice range with background', '2008-03-26 11:08:04.000000', NULL, 1),
(4588616, 660995, 76430, '<td valign="top">This has potential.  I wish it was lit better, sharper, and had the old person''s eyes in it.  With no eyes showing it detracts from it.</td>', 'This has potential.  I wish it was lit better, sharper, and had the old person''s eyes in it.  With no eyes showing it detracts from it.', '2008-03-26 11:09:00.000000', NULL, 1),
(4588622, 661305, 91900, '<td valign="top">The horse on the left missing legs is distracting. Love the subject matter and style.</td>', 'The horse on the left missing legs is distracting. Love the subject matter and style.', '2008-03-26 11:10:33.000000', NULL, 1),
(4588629, 662021, 91900, '<td valign="top">Nice interesting contrast. His face <i>might</i> be a little bright, but that could be my laptop monitor.</td>', 'Nice interesting contrast. His face might be a little bright, but that could be my laptop monitor.', '2008-03-26 11:12:32.000000', NULL, 1),
(4588630, 661390, 76430, '<td valign="top">I love this one.  A couple of suggestions, the painting on top diverts my attention; the plant also.  Maybe posed in a more plain environment in portrait mode would be better.  Good for them!</td>', 'I love this one.  A couple of suggestions, the painting on top diverts my attention; the plant also.  Maybe posed in a more plain environment in portrait mode would be better.  Good for them!', '2008-03-26 11:13:03.000000', NULL, 1),
(4588632, 662258, 91900, '<td valign="top">Nice contrast and DoF, wonderful.</td>', 'Nice contrast and DoF, wonderful.', '2008-03-26 11:13:19.000000', NULL, 1),
(4588638, 660679, 76430, '<td valign="top">Good pose.  Some better lighting would have really helped this one.</td>', 'Good pose.  Some better lighting would have really helped this one.', '2008-03-26 11:14:24.000000', NULL, 1),
(4588642, 661619, 91900, '<td valign="top">Wonderful composition, of man and background.  Very expressive.  Might by my laptop monitor, but subject''s hair seems to receive color....it looks green.</td>', 'Wonderful composition, of man and background.  Very expressive.  Might by my laptop monitor, but subject''s hair seems to receive color....it looks green.', '2008-03-26 11:15:32.000000', NULL, 1),
(4588660, 661530, 76430, '<td valign="top">Excellent capture</td>', 'Excellent capture', '2008-03-26 11:21:36.000000', NULL, 1),
(4588671, 661974, 91900, '<td valign="top">Wonderful texture</td>', 'Wonderful texture', '2008-03-26 11:25:59.000000', NULL, 1),
(4588681, 661709, 76430, '<td valign="top">Very nice pose, but it''s very noisy and needs better lighting.  It has sort of a whiterook look to it.</td>', 'Very nice pose, but it''s very noisy and needs better lighting.  It has sort of a whiterook look to it.', '2008-03-26 11:28:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4588688, 660163, 76430, '<td valign="top">I''m sure you''ve heard these issues, but first it''s too small, the dog is in focus, but the wife is not, it looks like the on-camera flash was used, creating hot spots on the front and reflection behind.  More lighting from the sides would have fixed much of that.</td>', 'I''m sure you''ve heard these issues, but first it''s too small, the dog is in focus, but the wife is not, it looks like the on-camera flash was used, creating hot spots on the front and reflection behind.  More lighting from the sides would have fixed much of that.', '2008-03-26 11:30:04.000000', NULL, 1),
(4588748, 662275, 70896, '<td valign="top">It''s a bit cheesy, but it works! I love the tone! 8</td>', 'It''s a bit cheesy, but it works! I love the tone! 8', '2008-03-26 11:49:56.000000', NULL, 1),
(4588750, 661709, 70896, '<td valign="top">I dont really like the color. But their expressions are really good.</td>', 'I dont really like the color. But their expressions are really good.', '2008-03-26 11:50:54.000000', NULL, 1),
(4588755, 660995, 70896, '<td valign="top">OOF</td>', 'OOF', '2008-03-26 11:53:24.000000', NULL, 1),
(4588756, 660995, 73942, '<td valign="top">Seems out of focus, was it intentional?.</td>', 'Seems out of focus, was it intentional?.', '2008-03-26 11:53:56.000000', NULL, 1),
(4588798, 660287, 87898, '<td valign="top">I really like the composition. :)</td>', 'I really like the composition. :)', '2008-03-26 12:15:41.000000', NULL, 1),
(4588801, 662107, 87898, '<td valign="top">The color tint was a good choice for this photo.</td>', 'The color tint was a good choice for this photo.', '2008-03-26 12:16:27.000000', NULL, 1),
(4588810, 661852, 73942, '<td valign="top">I like the colors.</td>', 'I like the colors.', '2008-03-26 12:21:49.000000', NULL, 1),
(4588824, 662219, 84124, '<td valign="top">You gotta be a dog owner to appreciate this ;-)  Well done.</td>', 'You gotta be a dog owner to appreciate this ;-)  Well done.', '2008-03-26 12:32:24.000000', NULL, 1),
(4588826, 660994, 84124, '<td valign="top">I didn''t think a studio shot would work for this challenge, but this one does, I like it a lot.  Lighting a hair blown out on her arm, but that''s a minor nitpik.  Well done.</td>', 'I didn''t think a studio shot would work for this challenge, but this one does, I like it a lot.  Lighting a hair blown out on her arm, but that''s a minor nitpik.  Well done.', '2008-03-26 12:33:39.000000', NULL, 1),
(4588827, 661200, 84124, '<td valign="top">Very creative take on the challenge, this is a great idea.  The execution of it missed by a hair (blurry toe) but that''s minor.</td>', 'Very creative take on the challenge, this is a great idea.  The execution of it missed by a hair (blurry toe) but that''s minor.', '2008-03-26 12:34:20.000000', NULL, 1),
(4588828, 660066, 60495, '<td valign="top">I love the look of this one and the intimacy of self is interestingly conveyed very well.</td>', 'I love the look of this one and the intimacy of self is interestingly conveyed very well.', '2008-03-26 12:34:39.000000', NULL, 1),
(4588832, 661866, 84124, '<td valign="top">Nice intimate shot, naked baby might have worked even better on this one.  Regardless, this one will do well.</td>', 'Nice intimate shot, naked baby might have worked even better on this one.  Regardless, this one will do well.', '2008-03-26 12:36:07.000000', NULL, 1),
(4588834, 661765, 84124, '<td valign="top">LOL!  Not sure if that''s love or holding on for dear life ;-)  Regardless, great shot.</td>', 'LOL!  Not sure if that''s love or holding on for dear life ;-)  Regardless, great shot.', '2008-03-26 12:36:50.000000', NULL, 1),
(4588835, 662244, 84124, '<td valign="top">Some shots just make you go "awwwww" :-)  well done.</td>', 'Some shots just make you go "awwwww" :-)  well done.', '2008-03-26 12:37:28.000000', NULL, 1),
(4588839, 662178, 84124, '<td valign="top">I get boob, you get a handful of digits.  I see the way this works.  A hair blown out on the hilights, but a striking shot nonetheless.  This works real well for this challenge.</td>', 'I get boob, you get a handful of digits.  I see the way this works.  A hair blown out on the hilights, but a striking shot nonetheless.  This works real well for this challenge.', '2008-03-26 12:38:14.000000', NULL, 1),
(4588842, 661652, 84124, '<td valign="top">This is one of the better couples shots in this challenge.  The model on the left looks a bit awkward in position, but that''s minor, overall the composition of this photo works well.</td>', 'This is one of the better couples shots in this challenge.  The model on the left looks a bit awkward in position, but that''s minor, overall the composition of this photo works well.', '2008-03-26 12:40:02.000000', NULL, 1),
(4588845, 662040, 84124, '<td valign="top">I like how candid this shot is, and it works because of that.  This is a good snapshot, but could have been better, there''s an overexposure of her shirt &amp; jeans, and you could have added a bit of softness, maybe a Gaus blur.  The all natural forest bed really lends itself to two hiking granola crunchers deep in one another, thus the overall shot works well.</td>', 'I like how candid this shot is, and it works because of that.  This is a good snapshot, but could have been better, there''s an overexposure of her shirt & jeans, and you could have added a bit of softness, maybe a Gaus blur.  The all natural forest bed really lends itself to two hiking granola crunchers deep in one another, thus the overall shot works well.', '2008-03-26 12:42:54.000000', NULL, 1),
(4588851, 661187, 84124, '<td valign="top">This is a well executed candid.  the soft border &amp; b&amp;w work well.  The facial expressions really carry this photo, this is the kind of family shot that should end up on a wall somewhere.</td>', 'This is a well executed candid.  the soft border & b&w work well.  The facial expressions really carry this photo, this is the kind of family shot that should end up on a wall somewhere.', '2008-03-26 12:45:12.000000', NULL, 1),
(4588855, 661937, 84124, '<td valign="top">Second foot shot I''ve seen in this challenge, I never would have thought of doing this, very creative!  This works real well and is perfectly executed, strongly lends itself to a long saturday morning sleep in.  Only suggestion is the addition of some soft blur to the shot.</td>', 'Second foot shot I''ve seen in this challenge, I never would have thought of doing this, very creative!  This works real well and is perfectly executed, strongly lends itself to a long saturday morning sleep in.  Only suggestion is the addition of some soft blur to the shot.', '2008-03-26 12:47:46.000000', NULL, 1),
(4588859, 660287, 84124, '<td valign="top">Terriers are so damn cute.  This dog must love your model, it''s actually standing still (something my terriers are unfamiliar with).</td>', 'Terriers are so damn cute.  This dog must love your model, it''s actually standing still (something my terriers are unfamiliar with).', '2008-03-26 12:48:34.000000', NULL, 1),
(4588860, 659875, 70000, '<td valign="top">With such awesome costumes and pretty ladies you could have gone so much more striking and different with the lighting. The lighting being so plain and flat really doesn''t fit with the subject matter. I would try going with some darker sharper side and backlighting maybe or something not so flat and light.</td>', 'With such awesome costumes and pretty ladies you could have gone so much more striking and different with the lighting. The lighting being so plain and flat really doesn''t fit with the subject matter. I would try going with some darker sharper side and backlighting maybe or something not so flat and light.', '2008-03-26 12:48:34.000000', NULL, 1),
(4588861, 660060, 84124, '<td valign="top">Bravo!  This is my fav "expecting" shot of the challenge.  Wouldn''t be surprised to see this do really well.</td>', 'Bravo!  This is my fav "expecting" shot of the challenge.  Wouldn''t be surprised to see this do really well.', '2008-03-26 12:49:25.000000', NULL, 1),
(4588866, 662142, 84124, '<td valign="top">My second "awwwww" of this challenge.  Adorable and well executed.  For uniqueness and execution, this one deserves to do real well.</td>', 'My second "awwwww" of this challenge.  Adorable and well executed.  For uniqueness and execution, this one deserves to do real well.', '2008-03-26 12:50:28.000000', NULL, 1),
(4588868, 661944, 84124, '<td valign="top">Cool shot!  A bit of a stretch on the challenge, but I definitely "get it", well done.</td>', 'Cool shot!  A bit of a stretch on the challenge, but I definitely "get it", well done.', '2008-03-26 12:51:12.000000', NULL, 1),
(4588872, 661685, 84124, '<td valign="top">Conversation or "negotiation"??? ;-)  Beautiful shot, intimacy is a bit implied, but that warm smile conveys it.</td>', 'Conversation or "negotiation"??? ;-)  Beautiful shot, intimacy is a bit implied, but that warm smile conveys it.', '2008-03-26 12:53:03.000000', NULL, 1),
(4588876, 662132, 84124, '<td valign="top">Oh my.  This is such a warm emotive shot, definitely one of my favorites.  This will do well.</td>', 'Oh my.  This is such a warm emotive shot, definitely one of my favorites.  This will do well.', '2008-03-26 12:54:19.000000', NULL, 1),
(4588878, 662198, 84124, '<td valign="top">Yikes!  Thinking out of the box is the first thing that comes to mind, then a handful of really bad puns  ;-)  6 for creativity.</td>', 'Yikes!  Thinking out of the box is the first thing that comes to mind, then a handful of really bad puns  ;-)  6 for creativity.', '2008-03-26 12:55:21.000000', NULL, 1),
(4588879, 661944, 24550, '<td valign="top">good take on the challenge.</td>', 'good take on the challenge.', '2008-03-26 12:55:41.000000', NULL, 1),
(4588881, 660916, 24550, '<td valign="top">hehe good capture.</td>', 'hehe good capture.', '2008-03-26 12:56:08.000000', NULL, 1),
(4588884, 660969, 24550, '<td valign="top">the lighting is a bit too harsh on the balls to really make this shot appealing, and the colors are a bit flat. seems like the lighting wasn''t really under your control as it looks like an outdoor shot of some sort of game, but a bit of contrast work could improve the overall "pop" of the shot, i think.</td>', 'the lighting is a bit too harsh on the balls to really make this shot appealing, and the colors are a bit flat. seems like the lighting wasn''t really under your control as it looks like an outdoor shot of some sort of game, but a bit of contrast work could improve the overall "pop" of the shot, i think.', '2008-03-26 12:57:01.000000', NULL, 1),
(4588885, 662258, 84124, '<td valign="top">The boy in the front that looks like he''s going to punch your lights out detracts a hair from the shot, but the rest of it works really well.  Hope to see some outtakes when the challenge is done.</td>', 'The boy in the front that looks like he''s going to punch your lights out detracts a hair from the shot, but the rest of it works really well.  Hope to see some outtakes when the challenge is done.', '2008-03-26 12:57:15.000000', NULL, 1),
(4588887, 662037, 84124, '<td valign="top">Another great father/son shot, glad to see us sensitive (hah!) he-men represented in this challenge.  Baby''s playful expression is priceless.</td>', 'Another great father/son shot, glad to see us sensitive (hah!) he-men represented in this challenge.  Baby''s playful expression is priceless.', '2008-03-26 12:58:05.000000', NULL, 1),
(4588890, 662146, 84124, '<td valign="top">For some reason I can''t stop staring at this photo ;-)  Well done, only one of it''s kind in this challenge.  Even without any facial expressions, this one really works.</td>', 'For some reason I can''t stop staring at this photo ;-)  Well done, only one of it''s kind in this challenge.  Even without any facial expressions, this one really works.', '2008-03-26 12:59:03.000000', NULL, 1),
(4588891, 660725, 84124, '<td valign="top">Very well executed!  two playful giddy schoolgirls sharing the secrets of the universe, would not be surprised to see this one in the top 10.</td>', 'Very well executed!  two playful giddy schoolgirls sharing the secrets of the universe, would not be surprised to see this one in the top 10.', '2008-03-26 12:59:52.000000', NULL, 1),
(4588893, 662176, 24550, '<td valign="top">good find, funny title</td>', 'good find, funny title', '2008-03-26 13:01:22.000000', NULL, 1),
(4588897, 661390, 84124, '<td valign="top">This really is like watching a grand finale, I''m 104 of 117 into the challenge and the last 5 or 6 shots just keep gettign better and better.  This is so well done, her lean into her, his keen stare, the arms, the hands, fabulous!  Not sure if it will do well with the DPC crowd, but I love it.  7.</td>', 'This really is like watching a grand finale, I''m 104 of 117 into the challenge and the last 5 or 6 shots just keep gettign better and better.  This is so well done, her lean into her, his keen stare, the arms, the hands, fabulous!  Not sure if it will do well with the DPC crowd, but I love it.  7.', '2008-03-26 13:03:20.000000', NULL, 1),
(4588971, 661765, 80458, '<td valign="top">Good shot and I love the title. Made me laugh out loud!</td>', 'Good shot and I love the title. Made me laugh out loud!', '2008-03-26 13:30:02.000000', NULL, 1),
