(4591605, 661729, 74559, '<td valign="top">What a lovely composition, and the tones are so soothing! A great comfort to the eye, this, found within so many tacky entries...</td>', 'What a lovely composition, and the tones are so soothing! A great comfort to the eye, this, found within so many tacky entries...', '2008-03-27 14:11:11.000000', NULL, 1),
(4591611, 660449, 74559, '<td valign="top">Sweet! Great take on this challenge, nice comp and color; intimacy probably was born in such groups of creatures :-)</td>', 'Sweet! Great take on this challenge, nice comp and color; intimacy probably was born in such groups of creatures :-)', '2008-03-27 14:14:40.000000', NULL, 1),
