(4591662, 660994, 91804, '<td valign="top">Great lighting and texture/detail, wish we could see more of the woman''s face or a slightly more ponderous expression.</td>', 'Great lighting and texture/detail, wish we could see more of the woman''s face or a slightly more ponderous expression.', '2008-03-27 14:43:55.000000', NULL, 1),
(4591664, 660449, 91804, '<td valign="top">Fantastic photo, do like the composition and detail, works perfectly within the theme.</td>', 'Fantastic photo, do like the composition and detail, works perfectly within the theme.', '2008-03-27 14:45:48.000000', NULL, 1),
(4591665, 661530, 91804, '<td valign="top">This one gave me a laugh.  Love the detail and color.</td>', 'This one gave me a laugh.  Love the detail and color.', '2008-03-27 14:47:03.000000', NULL, 1),
(4591668, 662165, 91804, '<td valign="top">Cats always win points with me, good adaptation of the theme, some funny shadows behind mom''s nose.  Processing might have the tongue a bit too red?</td>', 'Cats always win points with me, good adaptation of the theme, some funny shadows behind mom''s nose.  Processing might have the tongue a bit too red?', '2008-03-27 14:48:57.000000', NULL, 1),
(4591670, 661305, 91804, '<td valign="top">Blown background is distracting, maybe there''s a reason?</td>', 'Blown background is distracting, maybe there''s a reason?', '2008-03-27 14:50:51.000000', NULL, 1),
(4591671, 662209, 91804, '<td valign="top">Maybe a touch under-exposed for my taste but I do like the detail on the face and tattoos.  Uses the theme well.</td>', 'Maybe a touch under-exposed for my taste but I do like the detail on the face and tattoos.  Uses the theme well.', '2008-03-27 14:51:45.000000', NULL, 1),
(4591673, 661576, 91804, '<td valign="top">I could see this up in my room poster-size, great capture of intimacy.  Only improvements I could see would be either more or less motion blur on the hands, no flash reflection on the bottom of the guitar, or a little extra space on the left so that the end of the guitar isn''t "kissing" the edge of the frame.  One of my favorites.</td>', 'I could see this up in my room poster-size, great capture of intimacy.  Only improvements I could see would be either more or less motion blur on the hands, no flash reflection on the bottom of the guitar, or a little extra space on the left so that the end of the guitar isn''t "kissing" the edge of the frame.  One of my favorites.', '2008-03-27 14:53:59.000000', NULL, 1),
(4591679, 661866, 91804, '<td valign="top">Good capture, do like the lighting, great expression on kiddo''s face, wish we could see more of it, and maybe a slight distinction between his shirt and the background.  Fits well with the theme.</td>', 'Good capture, do like the lighting, great expression on kiddo''s face, wish we could see more of it, and maybe a slight distinction between his shirt and the background.  Fits well with the theme.', '2008-03-27 14:58:31.000000', NULL, 1),
(4591681, 662088, 91804, '<td valign="top">The more I look at this one, the more I like it... the light on the feet is great, wish there was a little more of that to go around?</td>', 'The more I look at this one, the more I like it... the light on the feet is great, wish there was a little more of that to go around?', '2008-03-27 14:59:40.000000', NULL, 1),
(4591685, 661711, 91804, '<td valign="top">Great detail and lighting, very clean image.</td>', 'Great detail and lighting, very clean image.', '2008-03-27 15:00:49.000000', NULL, 1),
(4591686, 662021, 91804, '<td valign="top">A little soft for my taste, but I do like the expression in his face... sort of a funny composition, not sure how this one was shot.</td>', 'A little soft for my taste, but I do like the expression in his face... sort of a funny composition, not sure how this one was shot.', '2008-03-27 15:01:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4591687, 661900, 91804, '<td valign="top">Definitely fits within the theme, interesting composition using the light on her back, that is quite nice.</td>', 'Definitely fits within the theme, interesting composition using the light on her back, that is quite nice.', '2008-03-27 15:03:16.000000', NULL, 1),
(4591689, 662258, 91804, '<td valign="top">Great use of b&amp;w for the different skin tones, I like it.  Bokeh on this lens is kind of funny, making the bike rider (?) a bit distracting in the background.</td>', 'Great use of b&w for the different skin tones, I like it.  Bokeh on this lens is kind of funny, making the bike rider (?) a bit distracting in the background.', '2008-03-27 15:04:54.000000', NULL, 1),
(4591694, 661200, 91804, '<td valign="top">One of my favorites, great lighting and shadows, sharp where it needs to be.  The only improvement were if the foot weren''t blurred on the right.</td>', 'One of my favorites, great lighting and shadows, sharp where it needs to be.  The only improvement were if the foot weren''t blurred on the right.', '2008-03-27 15:07:17.000000', NULL, 1),
(4591698, 662146, 91804, '<td valign="top">Woo hoo, certainly a bit of "intimacy", interesting DOF.  Do like.</td>', 'Woo hoo, certainly a bit of "intimacy", interesting DOF.  Do like.', '2008-03-27 15:08:11.000000', NULL, 1),
(4591701, 661577, 91804, '<td valign="top">Great composition IMO, wish she was a bit sharper and not blown out on the hilights.  Great example of intimacy.</td>', 'Great composition IMO, wish she was a bit sharper and not blown out on the hilights.  Great example of intimacy.', '2008-03-27 15:09:14.000000', NULL, 1),
(4591706, 659803, 91804, '<td valign="top">Had to laugh a bit when I saw this one, not quite sure what is implied in the title.  Left hand is a bit soft and some of the hilights look a tad funny, but overall a very interesting capture.</td>', 'Had to laugh a bit when I saw this one, not quite sure what is implied in the title.  Left hand is a bit soft and some of the hilights look a tad funny, but overall a very interesting capture.', '2008-03-27 15:10:29.000000', NULL, 1),
(4591708, 661681, 91804, '<td valign="top">Moving his right hand to her hip would make this shot infinitely better, great composition.</td>', 'Moving his right hand to her hip would make this shot infinitely better, great composition.', '2008-03-27 15:11:35.000000', NULL, 1),
(4591715, 661728, 91804, '<td valign="top">A tad cheezy IMO, but maybe that is intentional.  The guy could use a little light on the face.</td>', 'A tad cheezy IMO, but maybe that is intentional.  The guy could use a little light on the face.', '2008-03-27 15:13:24.000000', NULL, 1),
(4591718, 660998, 91804, '<td valign="top">I actually like this one for this challenge, interesting composition.  The guy could have a better expression on his face and some of the hilights on the top right may have been lost... a little tighter crop on the left may hide the slight distortion of the pillar.</td>', 'I actually like this one for this challenge, interesting composition.  The guy could have a better expression on his face and some of the hilights on the top right may have been lost... a little tighter crop on the left may hide the slight distortion of the pillar.', '2008-03-27 15:15:30.000000', NULL, 1),
(4592024, 661681, 57886, '<td valign="top">IMHO the best in this challenge... love the tones and :o)</td>', 'IMHO the best in this challenge... love the tones and :o)', '2008-03-27 17:42:36.000000', NULL, 1),
(4592104, 661900, 91483, '<td valign="top">Very nice, discrete and yet very intimate. I love it. Great shot.</td>', 'Very nice, discrete and yet very intimate. I love it. Great shot.', '2008-03-27 18:14:33.000000', NULL, 1),
(4592113, 661874, 91197, '<td valign="top">Nice shot. Vivid colors And I can c intimacy now!!!</td>', 'Nice shot. Vivid colors And I can c intimacy now!!!', '2008-03-27 18:18:59.000000', NULL, 1),
(4592244, 661932, 50695, '<td valign="top">You''re in a hotel room. The key is still in the door, so you rushed in. Perhaps dinner is only a minute after check-in. This evening is really important to you, so you take out a dress that you look reeeeeally good in and prep the makeup. <br/> <br/>Kind of a drab photo, though. But in the future, when we are all implanted with barcode readers, it will have more significance.</td>', 'You''re in a hotel room. The key is still in the door, so you rushed in. Perhaps dinner is only a minute after check-in. This evening is really important to you, so you take out a dress that you look reeeeeally good in and prep the makeup.  Kind of a drab photo, though. But in the future, when we are all implanted with barcode readers, it will have more significance.', '2008-03-27 19:20:19.000000', NULL, 1),
(4592248, 662082, 50695, '<td valign="top">I''m giving you a couple points for the grain, but your model is too posed and pouty to convey "intimacy" to me.</td>', 'I''m giving you a couple points for the grain, but your model is too posed and pouty to convey "intimacy" to me.', '2008-03-27 19:22:03.000000', NULL, 1),
(4592250, 662154, 50695, '<td valign="top">I like how the two bodies seem to be merged together.</td>', 'I like how the two bodies seem to be merged together.', '2008-03-27 19:23:14.000000', NULL, 1),
(4592254, 660996, 50695, '<td valign="top">I''m giving you a 6 for good acting.</td>', 'I''m giving you a 6 for good acting.', '2008-03-27 19:26:46.000000', NULL, 1),
(4592262, 661711, 50695, '<td valign="top">she looks like Aimee the Too! I''m not sure the kid is really into it, with that sidelong glance and all, but still a touching photo.</td>', 'she looks like Aimee the Too! I''m not sure the kid is really into it, with that sidelong glance and all, but still a touching photo.', '2008-03-27 19:30:27.000000', NULL, 1),
(4592278, 662107, 66267, '<td valign="top">Interesting perspective...</td>', 'Interesting perspective...', '2008-03-27 19:37:01.000000', NULL, 1),
(4592280, 661729, 50695, '<td valign="top">brilliant photojournalism. beautiful photo.<br/> <br/>Man, there is nothing even close to this in the rest of the challenge. I hope you get the blue. In the meantime I''m giving you my blue.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/bluepost.jpg'', strrpos(''//blackyak.com/dpc/bluepost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/bluepost.jpg"/></td>', 'brilliant photojournalism. beautiful photo. Man, there is nothing even close to this in the rest of the challenge. I hope you get the blue. In the meantime I''m giving you my blue. ', '2008-03-27 19:39:32.000000', NULL, 1),
