(4594935, 662107, 91665, '<td valign="top">nice touch on the sepia.</td>', 'nice touch on the sepia.', '2008-03-29 02:14:24.000000', NULL, 1),
(4594975, 661576, 89405, '<td valign="top">I really like this one.  You''ve given us a glimpse of a private and meaningful moment.  BTW - it''s hard to tell from the limited resolution image, but it looks like the guitar is strung for a right-handed player (conventionally, the thicker strings are on top).</td>', 'I really like this one.  You''ve given us a glimpse of a private and meaningful moment.  BTW - it''s hard to tell from the limited resolution image, but it looks like the guitar is strung for a right-handed player (conventionally, the thicker strings are on top).', '2008-03-29 05:29:29.000000', NULL, 1),
(4594977, 662142, 89405, '<td valign="top">One of my top picks for this challenge.  It looks very genuine, not posed and I just love the colors.</td>', 'One of my top picks for this challenge.  It looks very genuine, not posed and I just love the colors.', '2008-03-29 05:32:57.000000', NULL, 1),
(4595050, 660725, 11518, '<td valign="top">Beautiful capture! 10</td>', 'Beautiful capture! 10', '2008-03-29 07:35:06.000000', NULL, 1),
(4595053, 659875, 11518, '<td valign="top">Beautiful light nice, pose, fits the challenge. 10 from me.  But I suspect the prudes of DPC are gonna hammer this unfortunately.</td>', 'Beautiful light nice, pose, fits the challenge. 10 from me.  But I suspect the prudes of DPC are gonna hammer this unfortunately.', '2008-03-29 07:39:05.000000', NULL, 1),
(4595054, 662240, 11518, '<td valign="top">The big chunk of blown out sky at the top is distracting.  Some fill flash would have been useful here to light up the shadows without blowing out the sky.  I would have gotten closer to get just the couple and the train without the sky which adds nothing to the shot.  Nice capture and pose otherwise. 8</td>', 'The big chunk of blown out sky at the top is distracting.  Some fill flash would have been useful here to light up the shadows without blowing out the sky.  I would have gotten closer to get just the couple and the train without the sky which adds nothing to the shot.  Nice capture and pose otherwise. 8', '2008-03-29 07:42:23.000000', NULL, 1),
(4595118, 662178, 80542, '<td valign="top">Great capture but it''s so overexposed that a lot of the desired detail is lost.</td>', 'Great capture but it''s so overexposed that a lot of the desired detail is lost.', '2008-03-29 08:29:03.000000', NULL, 1),
(4595124, 661711, 80542, '<td valign="top">So many of the shots for this challenge show people who are obviously close, but not all speak to intimacy.  This one does it for me.  Beautiful photo and even more beautiful feeling it provokes.</td>', 'So many of the shots for this challenge show people who are obviously close, but not all speak to intimacy.  This one does it for me.  Beautiful photo and even more beautiful feeling it provokes.', '2008-03-29 08:32:18.000000', NULL, 1),
(4595131, 662215, 80542, '<td valign="top">Nice way to show intimacy &amp; nice use of b&amp;w.</td>', 'Nice way to show intimacy & nice use of b&w.', '2008-03-29 08:35:02.000000', NULL, 1),
(4595133, 662258, 80542, '<td valign="top">Great shot!</td>', 'Great shot!', '2008-03-29 08:35:20.000000', NULL, 1),
(4595136, 661732, 80542, '<td valign="top">I''m more impressed with your brave intimacy with the subject!  Great shot - excellent color &amp; clarity.</td>', 'I''m more impressed with your brave intimacy with the subject!  Great shot - excellent color & clarity.', '2008-03-29 08:37:36.000000', NULL, 1),
(4595137, 660287, 80542, '<td valign="top">sweet shot</td>', 'sweet shot', '2008-03-29 08:37:50.000000', NULL, 1),
(4595142, 662064, 80542, '<td valign="top">Beautiful.  It invokes feelings of love, romance, ultimately intimacy.</td>', 'Beautiful.  It invokes feelings of love, romance, ultimately intimacy.', '2008-03-29 08:39:31.000000', NULL, 1),
(4595148, 661728, 80542, '<td valign="top">Clarity is fantasic and great lighting.  Feels a bit too posed for me, but excellent photo.</td>', 'Clarity is fantasic and great lighting.  Feels a bit too posed for me, but excellent photo.', '2008-03-29 08:40:57.000000', NULL, 1),
(4595157, 661728, 17513, '<td valign="top">this is my fav out of all...you can see a real connection of intimacy.i love how hes touching her neck with the rose and how she is touching  his face/neck.beautiful picture</td>', 'this is my fav out of all...you can see a real connection of intimacy.i love how hes touching her neck with the rose and how she is touching  his face/neck.beautiful picture', '2008-03-29 08:47:19.000000', NULL, 1),
