(4595212, 661336, 15291, '<td valign="top">Nice image, the blue was a nice touch, but is a bit of a distraction.</td>', 'Nice image, the blue was a nice touch, but is a bit of a distraction.', '2008-03-29 10:12:20.000000', NULL, 1),
(4595215, 661305, 15291, '<td valign="top">Nice image, does seems a bit over exposed and it looks like you have a group of dead pixels.</td>', 'Nice image, does seems a bit over exposed and it looks like you have a group of dead pixels.', '2008-03-29 10:13:39.000000', NULL, 1),
