(4595219, 660596, 15291, '<td valign="top">Nicely done, a bit more light possibly.</td>', 'Nicely done, a bit more light possibly.', '2008-03-29 10:15:08.000000', NULL, 1),
(4595223, 661852, 15291, '<td valign="top">Nice image. The title gives me the feel of church. The image itself hit me as movie theather.</td>', 'Nice image. The title gives me the feel of church. The image itself hit me as movie theather.', '2008-03-29 10:17:32.000000', NULL, 1),
(4595231, 660987, 15291, '<td valign="top">Nicely done. I just don''t feel or see the intimacy here.</td>', 'Nicely done. I just don''t feel or see the intimacy here.', '2008-03-29 10:21:51.000000', NULL, 1),
(4595236, 661652, 15291, '<td valign="top">Nice image. Just a wee bit to much space to the right.</td>', 'Nice image. Just a wee bit to much space to the right.', '2008-03-29 10:22:53.000000', NULL, 1),
(4595242, 661654, 15291, '<td valign="top">Nice image, there just to far apart to convey any type of intimacy.</td>', 'Nice image, there just to far apart to convey any type of intimacy.', '2008-03-29 10:24:50.000000', NULL, 1),
