(4596075, 662120, 60047, '<td valign="top">Very nicely done.</td>', 'Very nicely done.', '2008-03-29 21:10:51.000000', NULL, 1),
(4596085, 660679, 60047, '<td valign="top">An interesting take on "Intimacy." I like the concept behind the picture. I think it would be more intimate and less unnatural if she didn''t have her hand holding her towel - this would allow for a more voyeuristic feel evoked in your title. It might also work better of the image in the mirror was in focus and the less interesting back side of the model be the part that is soft focus.</td>', 'An interesting take on "Intimacy." I like the concept behind the picture. I think it would be more intimate and less unnatural if she didn''t have her hand holding her towel - this would allow for a more voyeuristic feel evoked in your title. It might also work better of the image in the mirror was in focus and the less interesting back side of the model be the part that is soft focus.', '2008-03-29 21:17:51.000000', NULL, 1),
(4596086, 661651, 60047, '<td valign="top">Your title definitely helps make this fit.</td>', 'Your title definitely helps make this fit.', '2008-03-29 21:19:07.000000', NULL, 1),
(4596088, 661754, 60047, '<td valign="top">This is a great shot. The title could use some work to help the photo fit better with the challenge.</td>', 'This is a great shot. The title could use some work to help the photo fit better with the challenge.', '2008-03-29 21:22:52.000000', NULL, 1),
(4596091, 661928, 60047, '<td valign="top">Great concept for the challenge. The positioning of the lipstick is just a bit too staged and stiff. Despite the effectice furnishings, this is almost too noticeably done in a studio. Perhaps a tighter crop would have helped?</td>', 'Great concept for the challenge. The positioning of the lipstick is just a bit too staged and stiff. Despite the effectice furnishings, this is almost too noticeably done in a studio. Perhaps a tighter crop would have helped?', '2008-03-29 21:27:12.000000', NULL, 1),
(4596103, 661132, 60047, '<td valign="top">This is a wonderfully weird photo! I love the contrast between the three figures. His bliss contrasted with her bemusement nestled under this bizarrely large sculpture helps send this photo in to the land of surreality! Fascinating.</td>', 'This is a wonderfully weird photo! I love the contrast between the three figures. His bliss contrasted with her bemusement nestled under this bizarrely large sculpture helps send this photo in to the land of surreality! Fascinating.', '2008-03-29 21:31:06.000000', NULL, 1),
(4596105, 660287, 60047, '<td valign="top">Nice crisp B &amp; W. Well balanced contrast. The only thing I don''t get here is the eye on the right side of the dog...what happened to it?</td>', 'Nice crisp B & W. Well balanced contrast. The only thing I don''t get here is the eye on the right side of the dog...what happened to it?', '2008-03-29 21:32:41.000000', NULL, 1),
(4596109, 661769, 60047, '<td valign="top">Nice Macro. I wish it were sharpened up a tad more. I''m not getting "Intimacy," though.</td>', 'Nice Macro. I wish it were sharpened up a tad more. I''m not getting "Intimacy," though.', '2008-03-29 21:34:08.000000', NULL, 1),
(4596114, 662021, 60047, '<td valign="top">This is a great shot for this challenge. The only thing that takes away from the effectiveness of this shot is the highlights on the right that appear to be starting to erase the models from the right. What was this - a sheet?</td>', 'This is a great shot for this challenge. The only thing that takes away from the effectiveness of this shot is the highlights on the right that appear to be starting to erase the models from the right. What was this - a sheet?', '2008-03-29 21:36:53.000000', NULL, 1),
(4596118, 662218, 60047, '<td valign="top">Technically a good photo (the hand is starting to get blown out, though). If it weren''t for the title, I wouldn''t get it - but the cynicism behind the title explains the initial apparent lack of "Intimacy." This is an excellent example of a title working perfectly with a photograph to actually enhance the photograph. Nice job.</td>', 'Technically a good photo (the hand is starting to get blown out, though). If it weren''t for the title, I wouldn''t get it - but the cynicism behind the title explains the initial apparent lack of "Intimacy." This is an excellent example of a title working perfectly with a photograph to actually enhance the photograph. Nice job.', '2008-03-29 21:39:48.000000', NULL, 1),
(4596123, 662256, 60047, '<td valign="top">Animals feeding does not really evoke "Intimacy" for me. But then again, I grew up in the city and this may be my own personal limitation. It would work for me if the lamb was cuddling down to sleep next to the mother. I think this photo would do better with a POV angle down lower - more from the eye level of the animals.</td>', 'Animals feeding does not really evoke "Intimacy" for me. But then again, I grew up in the city and this may be my own personal limitation. It would work for me if the lamb was cuddling down to sleep next to the mother. I think this photo would do better with a POV angle down lower - more from the eye level of the animals.', '2008-03-29 21:43:30.000000', NULL, 1),
(4596125, 660457, 60047, '<td valign="top">Groan!!!</td>', 'Groan!!!', '2008-03-29 21:44:12.000000', NULL, 1),
(4596132, 660131, 60047, '<td valign="top">I think this photo would be better with the camera closer to street level. The shot is a bit incongruous with the title. That being said the subjects are really quite intriguing to me. The composition is good. I think you could do a lot better with this with different camera angles and crops. Excellent crispness.</td>', 'I think this photo would be better with the camera closer to street level. The shot is a bit incongruous with the title. That being said the subjects are really quite intriguing to me. The composition is good. I think you could do a lot better with this with different camera angles and crops. Excellent crispness.', '2008-03-29 21:49:34.000000', NULL, 1),
(4596133, 660994, 60047, '<td valign="top">This really works. I love the fact that she is looking at him and he is not looking at her - this adds complexity to the composition.  The only thing that leaves me scratching my head is the weird choice of border - what are you trying to say with that choice?</td>', 'This really works. I love the fact that she is looking at him and he is not looking at her - this adds complexity to the composition.  The only thing that leaves me scratching my head is the weird choice of border - what are you trying to say with that choice?', '2008-03-29 21:52:42.000000', NULL, 1),
(4596137, 661813, 60047, '<td valign="top">This is an immediate classic. This looks like something out of the seventies. Soft focus, sincere expressions between the models (not staged). Even the sepia adds to this photo. Wonderfully evocative and nostalgic. You really hit a home run, here.</td>', 'This is an immediate classic. This looks like something out of the seventies. Soft focus, sincere expressions between the models (not staged). Even the sepia adds to this photo. Wonderfully evocative and nostalgic. You really hit a home run, here.', '2008-03-29 21:55:36.000000', NULL, 1),
(4596141, 661764, 60047, '<td valign="top">AWWWWWW! I really wish the background was less defined (like a black one). I love the hat and I love the moment captured.</td>', 'AWWWWWW! I really wish the background was less defined (like a black one). I love the hat and I love the moment captured.', '2008-03-29 21:58:04.000000', NULL, 1),
(4596142, 661974, 60047, '<td valign="top">Neat! Great idea. Great execution.</td>', 'Neat! Great idea. Great execution.', '2008-03-29 21:58:34.000000', NULL, 1),
(4596148, 660996, 60047, '<td valign="top">I don''t understand how the title or the photo work together to do "Intimacy." The lighting from below is a bit harsh. I feel the photo has been unnaturally rotated 90 degrees clockwise from where it should be.</td>', 'I don''t understand how the title or the photo work together to do "Intimacy." The lighting from below is a bit harsh. I feel the photo has been unnaturally rotated 90 degrees clockwise from where it should be.', '2008-03-29 22:01:40.000000', NULL, 1),
(4596150, 661577, 60047, '<td valign="top">Oh that damned lens flare! If it weren''t for that - this picture would really be a stunner! What a great idea and a great use of both models.</td>', 'Oh that damned lens flare! If it weren''t for that - this picture would really be a stunner! What a great idea and a great use of both models.', '2008-03-29 22:02:58.000000', NULL, 1),
(4596151, 662168, 60047, '<td valign="top">This is a fun photograph to look at. Nice job.</td>', 'This is a fun photograph to look at. Nice job.', '2008-03-29 22:03:46.000000', NULL, 1),
(4596153, 661808, 60047, '<td valign="top">I don''t get it...What am I looking at? Are these marbels in a syrup? Is this a pomegranate under water? I am confused.</td>', 'I don''t get it...What am I looking at? Are these marbels in a syrup? Is this a pomegranate under water? I am confused.', '2008-03-29 22:05:35.000000', NULL, 1),
(4596154, 660998, 60047, '<td valign="top">Nice and innocent. I think a closer crop and crisper focus would work better, here.</td>', 'Nice and innocent. I think a closer crop and crisper focus would work better, here.', '2008-03-29 22:06:35.000000', NULL, 1),
(4596155, 662174, 60047, '<td valign="top">I love this shot. The colors are great. The titillation is wonderful. I just can''t quite get the photo and the title to fit into "Intimacy" for me, though.</td>', 'I love this shot. The colors are great. The titillation is wonderful. I just can''t quite get the photo and the title to fit into "Intimacy" for me, though.', '2008-03-29 22:08:41.000000', NULL, 1),
(4596158, 660912, 60047, '<td valign="top">I''m beginning to wonder about myself with all these animal shots. Like so many, this doesn''t cross into the anthropomorphism concept of "Intimacy" for me as much as it speaks of the biology lesson that birds must nest. I am beginning to think that this is more my limitation rather than your issue. I do think it might work better if they were touching beaks - as if in a kiss. With that out of the way, I really like this shot. I love the color of the eyes, the feather pattern and the sharpness of the focus.</td>', 'I''m beginning to wonder about myself with all these animal shots. Like so many, this doesn''t cross into the anthropomorphism concept of "Intimacy" for me as much as it speaks of the biology lesson that birds must nest. I am beginning to think that this is more my limitation rather than your issue. I do think it might work better if they were touching beaks - as if in a kiss. With that out of the way, I really like this shot. I love the color of the eyes, the feather pattern and the sharpness of the focus.', '2008-03-29 22:14:45.000000', NULL, 1),
(4596160, 661934, 60047, '<td valign="top">I rally like the concept behind what you are trying, here. I think the blown out whites detract from the effectiveness of your message.</td>', 'I rally like the concept behind what you are trying, here. I think the blown out whites detract from the effectiveness of your message.', '2008-03-29 22:15:59.000000', NULL, 1),
(4596161, 662244, 60047, '<td valign="top">This is a classic. Wonderfully intimate, I think the graininess, the B &amp; W, and the soft focus really works with this shot. Nice job.</td>', 'This is a classic. Wonderfully intimate, I think the graininess, the B & W, and the soft focus really works with this shot. Nice job.', '2008-03-29 22:17:13.000000', NULL, 1),
(4596163, 661728, 60047, '<td valign="top">This is a great shot. I think a wider aperture - blurring more of the background - would even be better. I love her expression very natural, sensual and relaxed.</td>', 'This is a great shot. I think a wider aperture - blurring more of the background - would even be better. I love her expression very natural, sensual and relaxed.', '2008-03-29 22:20:17.000000', NULL, 1),
(4596237, 661632, 73056, '<td valign="top">Love this concept. Would have been really great if the green lamp (or both) had been lit with a glow.</td>', 'Love this concept. Would have been really great if the green lamp (or both) had been lit with a glow.', '2008-03-29 23:34:13.000000', NULL, 1),
(4596422, 661681, 60195, '<td valign="top">My top pick in the challenge.  Obviously a pro wedding photographer (dwt?). Love the details in the highlights.  Definitely fits the theme... my only 10  :O)</td>', 'My top pick in the challenge.  Obviously a pro wedding photographer (dwt?). Love the details in the highlights.  Definitely fits the theme... my only 10  :O)', '2008-03-30 04:15:01.000000', NULL, 1),
(4596461, 660995, 32011, '<td valign="top">Great concept and a very sweet photo... suffers greatly because its OOF or softened too much.</td>', 'Great concept and a very sweet photo... suffers greatly because its OOF or softened too much.', '2008-03-30 06:16:17.000000', NULL, 1),
(4596484, 662241, 28742, '<td valign="top">Photographically / Technically / Lighting: Outstanding. As far as "Intimacy" - I don''t see it. The poses and expression looks awkward and she looks scared or concerned. Probably not what you wanted to hear, but that''s just my 2 cents. Others may disagree. :)</td>', 'Photographically / Technically / Lighting: Outstanding. As far as "Intimacy" - I don''t see it. The poses and expression looks awkward and she looks scared or concerned. Probably not what you wanted to hear, but that''s just my 2 cents. Others may disagree. :)', '2008-03-30 07:20:23.000000', NULL, 1),
(4596528, 661247, 57421, '<td valign="top">love the concept. GReat work on the composition (placement of the chaiurs, the diagonal...) and the colors.</td>', 'love the concept. GReat work on the composition (placement of the chaiurs, the diagonal...) and the colors.', '2008-03-30 08:18:55.000000', NULL, 1),
(4596529, 660596, 57421, '<td valign="top">great composition and use of low key to convey the feeling.</td>', 'great composition and use of low key to convey the feeling.', '2008-03-30 08:19:19.000000', NULL, 1),
(4596530, 660449, 57421, '<td valign="top">Great composition and photo op</td>', 'Great composition and photo op', '2008-03-30 08:19:40.000000', NULL, 1),
(4596534, 662064, 57421, '<td valign="top">quite like the mood. wonder how you did the background</td>', 'quite like the mood. wonder how you did the background', '2008-03-30 08:25:42.000000', NULL, 1),
(4596535, 661681, 57421, '<td valign="top">nice classic</td>', 'nice classic', '2008-03-30 08:25:52.000000', NULL, 1),
(4596536, 661900, 57421, '<td valign="top">great composition / silouhette. conveys well the topic of the challenge</td>', 'great composition / silouhette. conveys well the topic of the challenge', '2008-03-30 08:26:16.000000', NULL, 1),
(4596537, 662275, 57421, '<td valign="top">nice colors and tones.</td>', 'nice colors and tones.', '2008-03-30 08:26:29.000000', NULL, 1),
(4596554, 660995, 76598, '<td valign="top">The subject is great.  I think the photo would benefit from a crisper focus, more contrast, a fuller face on the adult, a less cluttered background and perhaps the baby turned toward the adult.</td>', 'The subject is great.  I think the photo would benefit from a crisper focus, more contrast, a fuller face on the adult, a less cluttered background and perhaps the baby turned toward the adult.', '2008-03-30 09:31:13.000000', NULL, 1),
(4596569, 661874, 91691, '<td valign="top">like the colours but would have been better without the branch in top left corner</td>', 'like the colours but would have been better without the branch in top left corner', '2008-03-30 09:50:01.000000', NULL, 1),
(4596586, 660596, 91691, '<td valign="top">i really like this it almost has hologram, would love to know how u did this effect</td>', 'i really like this it almost has hologram, would love to know how u did this effect', '2008-03-30 10:10:45.000000', NULL, 1),
(4596667, 662176, 65713, '<td valign="top">Not the best shot technically but still an incredible capture. 7 from me.</td>', 'Not the best shot technically but still an incredible capture. 7 from me.', '2008-03-30 12:17:52.000000', NULL, 1),
(4596679, 661530, 65713, '<td valign="top">Not the best DOF throughout the shot but to catch flies at it deserves a good vote, 7.</td>', 'Not the best DOF throughout the shot but to catch flies at it deserves a good vote, 7.', '2008-03-30 12:29:36.000000', NULL, 1),
(4596682, 662132, 65713, '<td valign="top">Think the idea is good and the composition is nice but would like to have seen the mother''s face more clearly.</td>', 'Think the idea is good and the composition is nice but would like to have seen the mother''s face more clearly.', '2008-03-30 12:31:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4596886, 661445, 2158, '<td valign="top">High key works well here.  I just wish the guy had taken his watch off - it looks a bit out of place.</td>', 'High key works well here.  I just wish the guy had taken his watch off - it looks a bit out of place.', '2008-03-30 15:02:06.000000', NULL, 1),
(4597110, 661187, 66201, '<td valign="top">Lovely conversion: pity about the distracting white fuzz at the bottom edge of the shot (fencing or top of railing?)...DPC will also not look kindly on the lack of sharpness in general. But a really lovely moment captured.</td>', 'Lovely conversion: pity about the distracting white fuzz at the bottom edge of the shot (fencing or top of railing?)...DPC will also not look kindly on the lack of sharpness in general. But a really lovely moment captured.', '2008-03-30 17:37:06.000000', NULL, 1),
(4597113, 662146, 66201, '<td valign="top">Striking... like the relatively small area in sharp focus with the body being almost a backdrop. Not sure that passion speaks so much about intimacy, as it does about... well.. um passion. Perhaps a separate topic. lovely conversion with gentle contrasts.</td>', 'Striking... like the relatively small area in sharp focus with the body being almost a backdrop. Not sure that passion speaks so much about intimacy, as it does about... well.. um passion. Perhaps a separate topic. lovely conversion with gentle contrasts.', '2008-03-30 17:38:55.000000', NULL, 1),
